import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry tanh_f32(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .s32 n_elts
)
{
    .reg .pred  %p_done, %p_vec, %p1, %p2, %p3;
    .reg .s32   %r_tid, %r_bid, %r_bdim, %r_gdim, %idx, %stride, %iter, %base, %tmp, %n, %nrem;
    .reg .u64   %in, %out, %off, %addr_in, %addr_out, %addr0, %addr1;
    .reg .f32   %x0, %x1, %x2, %x3, %y0, %y1, %y2, %y3;
    .reg .f32   %x, %y;
    // Load parameters
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.s32 %n,   [n_elts];
    // Compute thread/block/grid info
    mov.u32  %r_tid,  %tid.x;
    mov.u32  %r_bid,  %ctaid.x;
    mov.u32  %r_bdim, %ntid.x;
    mov.u32  %r_gdim, %nctaid.x;
    // Linear thread index
    mad.lo.s32 %idx, %r_bid, %r_bdim, %r_tid;
    // Stride = gridDim.x * blockDim.x
    mul.lo.s32 %stride, %r_gdim, %r_bdim;
    // Initialize iterator
    mov.s32 %iter, %idx;
LOOP:
    // Base element index = iter * 4
    shl.b32 %base, %iter, 2;
    // If base >= n, exit
    setp.ge.s32 %p_done, %base, %n;
    @%p_done bra DONE;
    // Byte offset and base addresses (off = iter * 16 bytes)
    mul.wide.s32 %off, %iter, 16;
    add.u64 %addr_in,  %in,  %off;
    add.u64 %addr_out, %out, %off;
    // If we have at least 4 elements remaining, take the vectorized path
    add.s32 %tmp, %base, 3;
    setp.lt.s32 %p_vec, %tmp, %n;
    @%p_vec bra VEC_PATH;
    // Scalar tail path (1-3 remaining elements)
    sub.s32 %nrem, %n, %base;
    // Element 0 (if nrem > 0)
    setp.gt.s32 %p1, %nrem, 0;
    @!%p1 bra INC;
    ld.global.f32 %x, [%addr_in];
    tanh.approx.f32 %y, %x;
    st.global.f32 [%addr_out], %y;
    // Element 1 (if nrem > 1)
    setp.gt.s32 %p2, %nrem, 1;
    @!%p2 bra INC;
    add.u64 %addr0, %addr_in, 4;
    add.u64 %addr1, %addr_out, 4;
    ld.global.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.f32 [%addr1], %y;
    // Element 2 (if nrem > 2)
    setp.gt.s32 %p3, %nrem, 2;
    @!%p3 bra INC;
    add.u64 %addr0, %addr_in, 8;
    add.u64 %addr1, %addr_out, 8;
    ld.global.f32 %x, [%addr0];
    tanh.approx.f32 %y, %x;
    st.global.f32 [%addr1], %y;
    bra INC;
VEC_PATH:
    ld.global.v4.f32 { %x0, %x1, %x2, %x3 }, [%addr_in];
    tanh.approx.f32 %y0, %x0;
    tanh.approx.f32 %y1, %x1;
    tanh.approx.f32 %y2, %x2;
    tanh.approx.f32 %y3, %x3;
    st.global.v4.f32 [%addr_out], { %y0, %y1, %y2, %y3 };
INC:
    add.s32 %iter, %iter, %stride;
    bra LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensor input.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew supports only float32 tensors.")
        if not x.is_contiguous():
            raise RuntimeError("ModelNew requires contiguous input tensor.")
        n = x.numel()
        y = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        module = _get_ptx_module()
        threads = 256
        n_vec = (n + 3) // 4
        blocks = (n_vec + threads - 1) // threads
        module.launch(
            "tanh_f32",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, y, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

